insert into public.role_permissions(role_id,permission) select id,'lab.orders.create' from public.roles where code='lab_assistant' on conflict do nothing;
insert into public.role_permissions(role_id,permission) select id,'lab.orders.receive' from public.roles where code='lab_assistant' on conflict do nothing;
insert into public.role_permissions(role_id,permission) select id,'library.manage' from public.roles where code='librarian' on conflict do nothing;
insert into public.role_permissions(role_id,permission) select id,'transport.view' from public.roles where code='transport_staff' on conflict do nothing;
insert into public.role_permissions(role_id,permission) select id,'transport.manage' from public.roles where code='transport_staff' on conflict do nothing;
insert into public.role_permissions(role_id,permission) select id,'transport.recordArrival' from public.roles where code='transport_staff' on conflict do nothing;
insert into public.role_permissions(role_id,permission) select id,'transport.recordDeparture' from public.roles where code='transport_staff' on conflict do nothing;
