insert into public.role_permissions(role_id,permission) select id,'inquiries.manage' from public.roles where code='head_of_school' on conflict do nothing;

create or replace function public.schoolos_has_role(org uuid, allowed public.school_role[]) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.user_roles ur join public.roles r on r.id=ur.role_id where ur.organization_id=org and ur.user_id=auth.uid() and r.code=any(allowed)); $$;
create or replace function public.schoolos_is_member(org uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles p where p.organization_id=org and p.id=auth.uid()); $$;
create or replace function public.schoolos_can_manage_org(org uuid) returns boolean language sql stable security definer set search_path=public as $$ select public.schoolos_has_role(org,array['admin','head_of_school']::public.school_role[]); $$;
create or replace function public.schoolos_has_permission(org uuid, requested text) returns boolean language sql stable security definer set search_path=public as $$ select public.schoolos_can_manage_org(org) or exists(select 1 from public.user_roles ur join public.role_permissions rp on rp.role_id=ur.role_id where ur.organization_id=org and ur.user_id=auth.uid() and (rp.permission='*' or rp.permission=requested)); $$;
create or replace function public.schoolos_is_student_owner(student uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.students s where s.id=student and s.profile_id=auth.uid()); $$;
create or replace function public.schoolos_teacher_can_access_student(org uuid, student uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.class_memberships teacher_membership join public.teachers t on t.id=teacher_membership.teacher_id join public.class_memberships student_membership on student_membership.class_id=teacher_membership.class_id where t.organization_id=org and t.profile_id=auth.uid() and student_membership.student_id=student and teacher_membership.membership_role in ('subject_teacher','class_teacher')); $$;
create or replace function public.schoolos_can_access_student(org uuid, student uuid) returns boolean language sql stable security definer set search_path=public as $$ select public.schoolos_is_student_owner(student) or public.schoolos_teacher_can_access_student(org,student) or public.schoolos_can_manage_org(org); $$;

-- All tables are organization-scoped. Generic policy grants an authenticated
-- member only records in their organization; sensitive tables get narrower policies below.
do $$ declare tbl text; begin foreach tbl in array array['profiles','user_roles','departments','teachers','staff','classes','class_memberships','teacher_class_logs','assignments','resources','lab_items','lab_transactions','lab_orders','library_books','book_copies','book_requests','calendar_events','timetables','exams','projects','project_milestones','maintenance_reports'] loop execute format('alter table public.%I enable row level security',tbl); execute format('create policy org_member_select on public.%I for select using (public.schoolos_is_member(organization_id))',tbl); execute format('create policy org_manager_write on public.%I for all using (public.schoolos_can_manage_org(organization_id)) with check (public.schoolos_can_manage_org(organization_id))',tbl); end loop; end $$;
alter table public.organizations enable row level security;
create policy organizations_member_read on public.organizations for select using (public.schoolos_is_member(id));
alter table public.roles enable row level security;
alter table public.role_permissions enable row level security;
create policy roles_authenticated_read on public.roles for select to authenticated using (true);
create policy role_permissions_authenticated_read on public.role_permissions for select to authenticated using (true);
alter table public.lab_order_items enable row level security;
create policy lab_order_items_member_read on public.lab_order_items for select using (exists(select 1 from public.lab_orders o where o.id=order_id and public.schoolos_is_member(o.organization_id)));
create policy lab_order_items_manager_write on public.lab_order_items for all using (exists(select 1 from public.lab_orders o where o.id=order_id and public.schoolos_can_manage_org(o.organization_id))) with check (exists(select 1 from public.lab_orders o where o.id=order_id and public.schoolos_can_manage_org(o.organization_id)));
alter table public.project_members enable row level security;
create policy project_members_member_read on public.project_members for select using (exists(select 1 from public.projects p where p.id=project_id and public.schoolos_is_member(p.organization_id)));
create policy project_members_manager_write on public.project_members for all using (exists(select 1 from public.projects p where p.id=project_id and public.schoolos_can_manage_org(p.organization_id))) with check (exists(select 1 from public.projects p where p.id=project_id and public.schoolos_can_manage_org(p.organization_id)));

-- Activity and audit history can contain sensitive workflow details. These are
-- intentionally scoped more narrowly than normal organization content.
alter table public.tracked_records enable row level security;
create policy tracked_records_authorized_read on public.tracked_records for select using (
  public.schoolos_can_manage_org(organization_id)
  or (coalesce((visibility->>'studentVisible')::boolean,false) and student_id is not null and public.schoolos_is_student_owner(student_id))
  or (student_id is not null and public.schoolos_teacher_can_access_student(organization_id,student_id))
  or (source_module='Lab' and public.schoolos_has_role(organization_id,array['lab_assistant']::public.school_role[]))
  or (source_module='Library' and public.schoolos_has_role(organization_id,array['librarian']::public.school_role[]))
  or (source_module='Transport' and public.schoolos_has_role(organization_id,array['transport_staff']::public.school_role[]))
);
create policy tracked_records_operational_write on public.tracked_records for all using (
  public.schoolos_has_permission(organization_id,'record.edit')
  or (source_module='Lab' and public.schoolos_has_role(organization_id,array['lab_assistant']::public.school_role[]))
  or (source_module='Library' and public.schoolos_has_role(organization_id,array['librarian']::public.school_role[]))
) with check (public.schoolos_is_member(organization_id));
alter table public.activity_events enable row level security;
create policy activity_events_authorized_read on public.activity_events for select using (
  public.schoolos_can_manage_org(organization_id)
  or (related_student_id is not null and public.schoolos_can_access_student(organization_id,related_student_id))
  or actor_id=auth.uid()
  or (module='Lab' and public.schoolos_has_role(organization_id,array['lab_assistant']::public.school_role[]))
  or (module='Library' and public.schoolos_has_role(organization_id,array['librarian']::public.school_role[]))
);
create policy activity_events_operational_write on public.activity_events for insert with check (public.schoolos_is_member(organization_id));
alter table public.audit_logs enable row level security;
create policy audit_logs_authorized_read on public.audit_logs for select using (public.schoolos_can_manage_org(organization_id) or actor_id=auth.uid());
create policy audit_logs_operational_write on public.audit_logs for insert with check (public.schoolos_is_member(organization_id));

-- Student-linked data is intentionally narrower than organization membership.
alter table public.students enable row level security;
create policy students_authorized_read on public.students for select using (public.schoolos_can_access_student(organization_id,id));
create policy students_manager_write on public.students for all using (public.schoolos_can_manage_org(organization_id)) with check (public.schoolos_can_manage_org(organization_id));
alter table public.attendance_records enable row level security;
create policy attendance_authorized_read on public.attendance_records for select using (public.schoolos_can_access_student(organization_id,student_id));
create policy attendance_teacher_write on public.attendance_records for all using (public.schoolos_teacher_can_access_student(organization_id,student_id) or public.schoolos_can_manage_org(organization_id)) with check (public.schoolos_teacher_can_access_student(organization_id,student_id) or public.schoolos_can_manage_org(organization_id));
alter table public.submissions enable row level security;
create policy submissions_authorized_read on public.submissions for select using (public.schoolos_can_access_student(organization_id,student_id));
create policy submissions_student_write on public.submissions for all using (public.schoolos_is_student_owner(student_id) or public.schoolos_teacher_can_access_student(organization_id,student_id) or public.schoolos_can_manage_org(organization_id)) with check (public.schoolos_is_student_owner(student_id) or public.schoolos_teacher_can_access_student(organization_id,student_id) or public.schoolos_can_manage_org(organization_id));
alter table public.grades enable row level security;
create policy grades_authorized_read on public.grades for select using (public.schoolos_can_access_student(organization_id,student_id));
create policy grades_teacher_write on public.grades for all using (public.schoolos_teacher_can_access_student(organization_id,student_id) or public.schoolos_can_manage_org(organization_id)) with check (public.schoolos_teacher_can_access_student(organization_id,student_id) or public.schoolos_can_manage_org(organization_id));
alter table public.damage_records enable row level security;
create policy damage_authorized_read on public.damage_records for select using ((student_visible and public.schoolos_is_student_owner(student_id)) or public.schoolos_teacher_can_access_student(organization_id,student_id) or public.schoolos_has_role(organization_id,array['lab_assistant','librarian','admin','head_of_school']::public.school_role[]));
create policy damage_operational_write on public.damage_records for all using (public.schoolos_has_role(organization_id,array['lab_assistant','librarian','admin','head_of_school']::public.school_role[])) with check (public.schoolos_has_role(organization_id,array['lab_assistant','librarian','admin','head_of_school']::public.school_role[]));
alter table public.lab_requests enable row level security;
create policy lab_requests_authorized_read on public.lab_requests for select using (requester_id=auth.uid() or public.schoolos_can_access_student(organization_id,student_id) or public.schoolos_has_role(organization_id,array['lab_assistant','admin','head_of_school']::public.school_role[]));
create policy lab_requests_authorized_write on public.lab_requests for all using (requester_id=auth.uid() or public.schoolos_has_role(organization_id,array['lab_assistant','admin','head_of_school']::public.school_role[])) with check (public.schoolos_is_member(organization_id));
alter table public.lab_usage enable row level security;
create policy lab_usage_authorized_read on public.lab_usage for select using ((student_id is not null and public.schoolos_can_access_student(organization_id,student_id)) or public.schoolos_has_role(organization_id,array['lab_assistant','admin','head_of_school']::public.school_role[]));
create policy lab_usage_operational_write on public.lab_usage for all using (public.schoolos_has_role(organization_id,array['lab_assistant','admin','head_of_school']::public.school_role[])) with check (public.schoolos_has_role(organization_id,array['lab_assistant','admin','head_of_school']::public.school_role[]));
alter table public.cas_experiences enable row level security;
create policy cas_authorized_read on public.cas_experiences for select using (public.schoolos_can_access_student(organization_id,student_id));
create policy cas_authorized_write on public.cas_experiences for all using (public.schoolos_is_student_owner(student_id) or public.schoolos_can_manage_org(organization_id)) with check (public.schoolos_is_student_owner(student_id) or public.schoolos_can_manage_org(organization_id));
alter table public.transport_notices enable row level security;
create policy transport_authorized_read on public.transport_notices for select using ((student_visible and public.schoolos_is_student_owner(student_id)) or public.schoolos_teacher_can_access_student(organization_id,student_id) or public.schoolos_has_role(organization_id,array['transport_staff','admin','head_of_school']::public.school_role[]));
create policy transport_authorized_write on public.transport_notices for all using (public.schoolos_teacher_can_access_student(organization_id,student_id) or public.schoolos_has_role(organization_id,array['transport_staff','admin','head_of_school']::public.school_role[])) with check (public.schoolos_is_member(organization_id));
alter table public.buses enable row level security;
alter table public.bus_arrival_records enable row level security;
alter table public.bus_departure_records enable row level security;
alter table public.transport_activity enable row level security;
create policy buses_transport_read on public.buses for select using (public.schoolos_has_role(organization_id,array['transport_staff','admin','head_of_school']::public.school_role[]));
create policy buses_transport_write on public.buses for all using (public.schoolos_has_role(organization_id,array['transport_staff','admin','head_of_school']::public.school_role[])) with check (public.schoolos_has_role(organization_id,array['transport_staff','admin','head_of_school']::public.school_role[]));
create policy arrival_transport_read on public.bus_arrival_records for select using (public.schoolos_has_role(organization_id,array['transport_staff','admin','head_of_school']::public.school_role[]));
create policy arrival_transport_write on public.bus_arrival_records for all using (public.schoolos_has_role(organization_id,array['transport_staff','admin','head_of_school']::public.school_role[])) with check (public.schoolos_has_role(organization_id,array['transport_staff','admin','head_of_school']::public.school_role[]));
create policy departure_transport_read on public.bus_departure_records for select using (public.schoolos_has_role(organization_id,array['transport_staff','admin','head_of_school']::public.school_role[]));
create policy departure_transport_write on public.bus_departure_records for all using (public.schoolos_has_role(organization_id,array['transport_staff','admin','head_of_school']::public.school_role[])) with check (public.schoolos_has_role(organization_id,array['transport_staff','admin','head_of_school']::public.school_role[]));
create policy activity_transport_read on public.transport_activity for select using (public.schoolos_has_role(organization_id,array['transport_staff','admin','head_of_school']::public.school_role[]));
create policy activity_transport_write on public.transport_activity for insert with check (public.schoolos_has_role(organization_id,array['transport_staff','admin','head_of_school']::public.school_role[]));
alter table public.notifications enable row level security;
create policy notifications_own_read on public.notifications for select using (user_id=auth.uid());
create policy notifications_manager_write on public.notifications for all using (public.schoolos_can_manage_org(organization_id)) with check (public.schoolos_can_manage_org(organization_id));
alter table public.borrowed_assets enable row level security;
create policy borrowed_assets_authorized_read on public.borrowed_assets for select using ((student_id is not null and public.schoolos_can_access_student(organization_id,student_id)) or public.schoolos_has_role(organization_id,array['librarian','lab_assistant','admin','head_of_school']::public.school_role[]));
create policy borrowed_assets_operational_write on public.borrowed_assets for all using (public.schoolos_has_role(organization_id,array['librarian','lab_assistant','admin','head_of_school']::public.school_role[])) with check (public.schoolos_has_role(organization_id,array['librarian','lab_assistant','admin','head_of_school']::public.school_role[]));

alter table public.student_records enable row level security;
create policy student_records_student_read on public.student_records for select using (student_visible and exists(select 1 from public.students s where s.id=student_id and s.profile_id=auth.uid()));
create policy student_records_teacher_read on public.student_records for select using (not restricted and public.schoolos_has_role(organization_id,array['teacher']::public.school_role[]));
create policy student_records_sensitive_permission on public.student_records for select using (public.schoolos_has_permission(organization_id,'student.records.sensitive'));
create policy student_records_staff_write on public.student_records for all using (public.schoolos_has_permission(organization_id,'record.edit')) with check (public.schoolos_has_permission(organization_id,'record.edit'));
alter table public.inquiries enable row level security;
alter table public.inquiry_messages enable row level security;
alter table public.inquiry_internal_notes enable row level security;
create policy inquiries_participant_read on public.inquiries for select using ((not restricted and public.schoolos_is_member(organization_id)) or created_by=auth.uid() or assigned_to=auth.uid() or public.schoolos_has_permission(organization_id,'inquiries.restricted'));
create policy inquiries_participant_write on public.inquiries for all using (created_by=auth.uid() or assigned_to=auth.uid() or public.schoolos_has_permission(organization_id,'inquiries.manage')) with check (public.schoolos_is_member(organization_id));
create policy inquiry_messages_participant_read on public.inquiry_messages for select using (exists(select 1 from public.inquiries i where i.id=inquiry_id and ((not i.restricted and not private and public.schoolos_is_member(i.organization_id)) or i.created_by=auth.uid() or i.assigned_to=auth.uid() or public.schoolos_has_permission(i.organization_id,'inquiries.restricted'))));
create policy inquiry_messages_participant_write on public.inquiry_messages for insert with check (exists(select 1 from public.inquiries i where i.id=inquiry_id and (i.created_by=auth.uid() or i.assigned_to=auth.uid() or public.schoolos_has_permission(i.organization_id,'inquiries.manage'))));
create policy inquiry_notes_staff_read on public.inquiry_internal_notes for select using (public.schoolos_has_permission(organization_id,'inquiries.viewAll') or author_id=auth.uid());
create policy inquiry_notes_staff_write on public.inquiry_internal_notes for all using (public.schoolos_has_permission(organization_id,'inquiries.manage')) with check (public.schoolos_has_permission(organization_id,'inquiries.manage'));

insert into storage.buckets(id,name,public) values ('assignment-submissions','assignment-submissions',false),('class-resources','class-resources',false),('project-files','project-files',false),('cas-evidence','cas-evidence',false),('inquiry-attachments','inquiry-attachments',false),('maintenance-images','maintenance-images',false),('lab-images','lab-images',false),('library-covers','library-covers',true),('documents','documents',false) on conflict(id) do nothing;
drop policy if exists schoolos_storage_read on storage.objects;
drop policy if exists schoolos_storage_write on storage.objects;
create policy schoolos_storage_read on storage.objects for select using (bucket_id='library-covers' or (auth.role()='authenticated' and exists(select 1 from public.profiles p where p.id=auth.uid() and storage.objects.name like p.organization_id::text || '/%')));
create policy schoolos_storage_write on storage.objects for insert with check (auth.role()='authenticated' and bucket_id in ('assignment-submissions','class-resources','project-files','cas-evidence','inquiry-attachments','maintenance-images','lab-images','library-covers','documents') and exists(select 1 from public.profiles p where p.id=auth.uid() and storage.objects.name like p.organization_id::text || '/%'));
